export function Carousel({
  transition = "{{transition}}",
  accent = "{{accent}}",
  showArrows = {{showArrows}},
  radius = {{radius}},
}) {
  const fills = ["#A8E6C1", "#BFD9F2", "#F5C2E0"];
  return (
    <div className={`carousel-rc carousel-rc--${transition}`} style={{ maxWidth: 360, font: "13px/1.4 system-ui, sans-serif", color: "#241430", "--accent": accent }}>
      <input className="carousel-rc__radio" type="radio" name="carousel-rc-slide" id="carousel-rc-s1" defaultChecked />
      <input className="carousel-rc__radio" type="radio" name="carousel-rc-slide" id="carousel-rc-s2" />
      <input className="carousel-rc__radio" type="radio" name="carousel-rc-slide" id="carousel-rc-s3" />

      <div className="carousel-rc__viewport" style={{ position: "relative", overflow: "hidden", border: "1px solid #24143022", background: "#FAF7F2", borderRadius: radius }}>
        <div className="carousel-rc__track" style={{ display: "flex", width: "300%" }}>
          {fills.map((fill, i) => (
            <figure key={i} className="carousel-rc__slide" style={{ flex: "0 0 33.333%", margin: 0, aspectRatio: "5 / 3" }} aria-hidden="true">
              <svg viewBox="0 0 400 240" width="100%" height="100%" style={{ display: "block" }}><rect width="400" height="240" fill={fill} /><circle cx="200" cy="120" r="60" fill="#FAF7F2" /></svg>
            </figure>
          ))}
        </div>
        {showArrows && (
          <div className="carousel-rc__arrows" style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 8px", pointerEvents: "none" }}>
            <label className="carousel-rc__arrow carousel-rc__arrow--for-1" htmlFor="carousel-rc-s3" aria-label="Previous slide">&#8249;</label>
            <label className="carousel-rc__arrow carousel-rc__arrow--for-1" htmlFor="carousel-rc-s2" aria-label="Next slide">&#8250;</label>
            <label className="carousel-rc__arrow carousel-rc__arrow--for-2" htmlFor="carousel-rc-s1" aria-label="Previous slide">&#8249;</label>
            <label className="carousel-rc__arrow carousel-rc__arrow--for-2" htmlFor="carousel-rc-s3" aria-label="Next slide">&#8250;</label>
            <label className="carousel-rc__arrow carousel-rc__arrow--for-3" htmlFor="carousel-rc-s2" aria-label="Previous slide">&#8249;</label>
            <label className="carousel-rc__arrow carousel-rc__arrow--for-3" htmlFor="carousel-rc-s1" aria-label="Next slide">&#8250;</label>
          </div>
        )}
      </div>

      <div className="carousel-rc__dots" style={{ display: "flex", gap: 6, justifyContent: "center", marginTop: 10 }}>
        <label className="carousel-rc__dot" htmlFor="carousel-rc-s1" aria-label="Go to slide 1" />
        <label className="carousel-rc__dot" htmlFor="carousel-rc-s2" aria-label="Go to slide 2" />
        <label className="carousel-rc__dot" htmlFor="carousel-rc-s3" aria-label="Go to slide 3" />
      </div>

      <style>{`
        .carousel-rc__radio { position: absolute; opacity: 0; width: 1px; height: 1px; overflow: hidden; }
        .carousel-rc__track { transition: transform .4s ease; }
        #carousel-rc-s1:checked ~ .carousel-rc__viewport .carousel-rc__track { transform: translateX(0%); }
        #carousel-rc-s2:checked ~ .carousel-rc__viewport .carousel-rc__track { transform: translateX(-33.333%); }
        #carousel-rc-s3:checked ~ .carousel-rc__viewport .carousel-rc__track { transform: translateX(-66.666%); }
        .carousel-rc--fade .carousel-rc__track { width: 100%; transition: none; transform: none !important; position: relative; }
        .carousel-rc--fade .carousel-rc__slide { position: absolute; inset: 0; opacity: 0; transition: opacity .5s ease; }
        .carousel-rc--fade #carousel-rc-s1:checked ~ .carousel-rc__viewport .carousel-rc__slide:nth-child(1) { opacity: 1; }
        .carousel-rc--fade #carousel-rc-s2:checked ~ .carousel-rc__viewport .carousel-rc__slide:nth-child(2) { opacity: 1; }
        .carousel-rc--fade #carousel-rc-s3:checked ~ .carousel-rc__viewport .carousel-rc__slide:nth-child(3) { opacity: 1; }
        .carousel-rc__arrow { display: none; align-items: center; justify-content: center; width: 28px; height: 28px; border-radius: 50%; background: #FAF7F2cc; color: #241430; cursor: pointer; font-size: 16px; line-height: 1; text-decoration: none; pointer-events: auto; }
        .carousel-rc__arrow:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
        #carousel-rc-s1:checked ~ .carousel-rc__viewport .carousel-rc__arrow--for-1 { display: flex; }
        #carousel-rc-s2:checked ~ .carousel-rc__viewport .carousel-rc__arrow--for-2 { display: flex; }
        #carousel-rc-s3:checked ~ .carousel-rc__viewport .carousel-rc__arrow--for-3 { display: flex; }
        .carousel-rc__dot { display: block; width: 8px; height: 8px; border-radius: 50%; background: #24143033; cursor: pointer; }
        .carousel-rc__dot:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
        #carousel-rc-s1:checked ~ .carousel-rc__dots label:nth-of-type(1) { background: var(--accent); }
        #carousel-rc-s2:checked ~ .carousel-rc__dots label:nth-of-type(2) { background: var(--accent); }
        #carousel-rc-s3:checked ~ .carousel-rc__dots label:nth-of-type(3) { background: var(--accent); }
      `}</style>
    </div>
  );
}
